-- Project Management System SQL target snapshot, issue #31.
-- PostgreSQL 16. Empty database only. This is not the active Prisma/runtime schema.
-- No business rows, credentials, roles, owners, or database names.
-- The migration runner owns BEGIN/COMMIT. Do not add transaction control here.
-- Apply only with scripts/sql-migrate.mjs and an explicit isolated target.
-- Timestamp defaults use Asia/Bangkok wall-clock time, independent of the client TimeZone.
-- Primary keys are BIGINT GENERATED BY DEFAULT AS IDENTITY
-- (START WITH 1 INCREMENT BY 1 NO CYCLE). Gaps are allowed. Do not renumber rows.
-- Every table also has an immutable random UUIDv4 public_id for client references.
-- Numeric keys remain internal; all relational FKs use id.
-- Naming: plural snake_case tables, snake_case columns, indexes and enum types.
-- Runtime evidence: app/api and lib, including Project DELETE relation counts.
-- Comment and Notification have no runtime queries and are excluded.
-- project_members, project_documents, project_milestones and activity_logs are
-- retained because the current Project DELETE handler queries their row counts.
-- schema_migrations is required by the SQL migration runner. The legacy ID
-- mapping table is excluded until a data migration actually uses it.
-- Names here require explicit Prisma mappings at the future SQL runtime cutover.
-- activity_logs are append-only; their foreign keys use RESTRICT on delete/update.
-- External reference project_id is a local PMS project, as written and compared
-- by lib/gitlab-issue-import.ts, so it is a BIGINT foreign key. External provider IDs stay TEXT.

CREATE FUNCTION pms_bangkok_now() RETURNS timestamp(3) WITHOUT TIME ZONE
LANGUAGE sql
VOLATILE
SET search_path = pg_catalog
AS $pms$
  SELECT pg_catalog.timezone('Asia/Bangkok', pg_catalog.clock_timestamp())::timestamp(3)
$pms$;

CREATE FUNCTION pms_bangkok_today() RETURNS date
LANGUAGE sql
VOLATILE
SET search_path = pg_catalog
AS $pms$
  SELECT (pg_catalog.timezone('Asia/Bangkok', pg_catalog.clock_timestamp()))::date
$pms$;

CREATE FUNCTION pms_stamp_timestamps() RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $pms$
DECLARE
  preserve text;
  changed boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.public_id IS DISTINCT FROM OLD.public_id THEN
    RAISE EXCEPTION '% public_id cannot be changed', TG_TABLE_NAME USING ERRCODE = '55000';
  END IF;
  preserve := pg_catalog.current_setting('pms.preserve_source_timestamps', true);
  IF TG_OP = 'INSERT' THEN
    IF preserve IS DISTINCT FROM 'on' THEN
      NEW.created_at := public.pms_bangkok_now();
      NEW.updated_at := NEW.created_at;
    END IF;
    RETURN NEW;
  END IF;
  IF preserve IS DISTINCT FROM 'on' THEN
    NEW.created_at := OLD.created_at;
    changed := (pg_catalog.to_jsonb(NEW) - 'created_at' - 'updated_at')
      IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) - 'created_at' - 'updated_at');
    IF changed THEN
      NEW.updated_at := public.pms_bangkok_now();
    ELSE
      NEW.updated_at := OLD.updated_at;
    END IF;
  END IF;
  RETURN NEW;
END;
$pms$;

CREATE FUNCTION pms_stamp_created_at() RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $pms$
BEGIN
  IF pg_catalog.current_setting('pms.preserve_source_timestamps', true) IS DISTINCT FROM 'on' THEN
    NEW.created_at := public.pms_bangkok_now();
  END IF;
  RETURN NEW;
END;
$pms$;

CREATE FUNCTION pms_reject_immutable_row() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $pms$
BEGIN
  RAISE EXCEPTION '% cannot be updated or deleted', TG_TABLE_NAME
    USING ERRCODE = '55000';
END;
$pms$;

CREATE FUNCTION pms_align_identity(target pg_catalog.regclass) RETURNS bigint
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $pms$
DECLARE
  sequence_name text;
  max_id bigint;
BEGIN
  sequence_name := pg_catalog.pg_get_serial_sequence(target::text, 'id');
  IF sequence_name IS NULL THEN
    RAISE EXCEPTION 'identity sequence missing';
  END IF;
  EXECUTE format('SELECT max(id) FROM %s', target) INTO max_id;
  IF max_id IS NULL THEN
    PERFORM pg_catalog.setval(sequence_name, 1, false);
    RETURN 1;
  END IF;
  PERFORM pg_catalog.setval(sequence_name, max_id, true);
  RETURN max_id + 1;
END;
$pms$;

CREATE TYPE "work_item_kind" AS ENUM ('Incident', 'Issue', 'Task');
CREATE TYPE "work_item_priority" AS ENUM ('none', 'low', 'medium', 'high', 'urgent');
CREATE TYPE "work_item_role" AS ENUM ('Developer', 'infra', 'SA');
CREATE TYPE "work_item_status" AS ENUM ('backlog', 'todo', 'in-progress', 'blocked', 'sa-testing', 'pm-testing', 'completed', 'cancelled');
CREATE TYPE "user_theme" AS ENUM ('light', 'dark', 'special-dark');
CREATE TYPE "user_locale" AS ENUM ('th', 'en');

CREATE TABLE "users" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "password_hash" TEXT NOT NULL,
    "role" TEXT NOT NULL DEFAULT 'member',
    "avatar_url" TEXT,
    "phone" TEXT,
    "theme" "user_theme" NOT NULL DEFAULT 'light',
    "locale" "user_locale" NOT NULL DEFAULT 'th',
    "status" TEXT NOT NULL DEFAULT 'Active',
    "joined_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    CONSTRAINT "users_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "users_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "companies" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "code" TEXT,
    "display_name" TEXT,
    "location" TEXT,
    "name" TEXT NOT NULL,
    "industry" TEXT,
    "email" TEXT,
    "phone" TEXT,
    "address" TEXT,
    "website_url" TEXT,
    "logo_url" TEXT,
    "description" TEXT,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    CONSTRAINT "companies_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "companies_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "projects" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "name" TEXT NOT NULL,
    "description" TEXT,
    "status" TEXT NOT NULL DEFAULT 'Planning',
    "priority" TEXT NOT NULL DEFAULT 'Medium',
    "start_date" DATE NOT NULL,
    "due_date" DATE NOT NULL,
    "budget_amount" DECIMAL(65,30),
    "spent_amount" DECIMAL(65,30) DEFAULT 0,
    "progress_percent" INTEGER NOT NULL DEFAULT 0,
    "color" TEXT,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "creator_id" BIGINT,
    "company_id" BIGINT NOT NULL,
    CONSTRAINT "projects_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "projects_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "project_members" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "role" TEXT NOT NULL DEFAULT 'member',
    "joined_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "project_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    CONSTRAINT "project_members_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "project_members_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "work_items" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "title" TEXT NOT NULL,
    "description" TEXT,
    "kind" "work_item_kind" NOT NULL,
    "priority" "work_item_priority" NOT NULL DEFAULT 'none',
    "functional_role" "work_item_role",
    "status" "work_item_status" NOT NULL DEFAULT 'backlog',
    "type_labels" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "work_date" DATE,
    "due_date" DATE,
    "submitted_at" TIMESTAMP(3) WITHOUT TIME ZONE,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "project_id" BIGINT NOT NULL,
    "assignee_id" BIGINT NOT NULL,
    CONSTRAINT "work_items_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "work_items_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "external_project_mappings" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "provider" TEXT NOT NULL DEFAULT 'gitlab',
    "instance_url" TEXT NOT NULL,
    "external_project_id" TEXT NOT NULL,
    "project_id" BIGINT NOT NULL,
    "approved_label_map" JSONB NOT NULL DEFAULT '{}'::JSONB,
    "first_sync_approved_at" TIMESTAMP(3) WITHOUT TIME ZONE,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    CONSTRAINT "external_project_mappings_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "external_project_mappings_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "external_work_item_references" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "provider" TEXT NOT NULL DEFAULT 'gitlab',
    "instance_url" TEXT NOT NULL,
    "external_project_id" TEXT NOT NULL,
    "external_issue_id" TEXT NOT NULL,
    "external_issue_number" TEXT NOT NULL,
    "external_url" TEXT NOT NULL,
    "project_id" BIGINT NOT NULL,
    "remote_created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL,
    "remote_updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL,
    "last_synced_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL,
    "work_item_id" BIGINT NOT NULL,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    CONSTRAINT "external_work_item_references_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "external_work_item_references_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "project_milestones" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "name" TEXT NOT NULL,
    "description" TEXT,
    "due_date" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'Not Started',
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "project_id" BIGINT NOT NULL,
    CONSTRAINT "project_milestones_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "project_milestones_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "project_documents" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "name" TEXT NOT NULL,
    "description" TEXT,
    "file_url" TEXT NOT NULL,
    "file_size_bytes" INTEGER,
    "file_type" TEXT,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "project_id" BIGINT,
    "uploader_id" BIGINT,
    CONSTRAINT "project_documents_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "project_documents_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "work_logs" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "description" TEXT,
    "remarks" TEXT,
    "hours" DECIMAL(65,30) NOT NULL,
    "work_date" DATE NOT NULL DEFAULT public.pms_bangkok_today(),
    "status" TEXT,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "updated_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "user_id" BIGINT NOT NULL,
    "project_id" BIGINT,
    "work_item_id" BIGINT,
    CONSTRAINT "work_logs_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "work_logs_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "activity_logs" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "action" TEXT NOT NULL,
    "entity" TEXT NOT NULL,
    "entity_id" TEXT NOT NULL,
    "description" TEXT,
    "metadata" JSONB,
    "created_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "user_id" BIGINT,
    "project_id" BIGINT,
    CONSTRAINT "activity_logs_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "activity_logs_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "schema_migrations" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1 NO CYCLE) NOT NULL,
    "public_id" UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid(),
    "version" TEXT NOT NULL,
    "checksum" TEXT NOT NULL,
    "schema_revision" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "applied_at" TIMESTAMP(3) WITHOUT TIME ZONE NOT NULL DEFAULT public.pms_bangkok_now(),
    "script_name" TEXT NOT NULL,
    "target_label" TEXT NOT NULL,
    CONSTRAINT "schema_migrations_public_id_key" UNIQUE ("public_id"),
    CONSTRAINT "schema_migrations_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "schema_migrations_version_key" UNIQUE ("version"),
    CONSTRAINT "schema_migrations_checksum_format" CHECK ("checksum" ~ '^[0-9a-f]{64}$'),
    CONSTRAINT "schema_migrations_status_applied" CHECK ("status" = 'applied')
);

